"""Source/hash verified four-pair gallery across reused baseline render receipts."""
from pathlib import Path
import json,hashlib,os,html
from PIL import Image
r=Path(__file__).resolve().parents[3];d=r/'data/venue_refs/floor_plans_v3/commercial_office_floor_02';out=d/'planters113_review';out.mkdir(exist_ok=True);names=[x['name'] for x in json.loads((d/'planters113_matched_views.json').read_text())];candidate=json.loads((d/'planters113_candidate_cpu/candidate/render_receipt.json').read_text());assert candidate['source_unchanged'];assert hashlib.sha256(Path(candidate['source']).read_bytes()).hexdigest()==candidate['source_sha256'];pairs=[];sections=[]
for i,name in enumerate(names):
 folder='planters113_baseline_close_cpu' if 'close' in name else 'taskchairs112_candidate_cpu';base=json.loads((d/folder/'candidate/render_receipt.json').read_text());assert base['source_unchanged'];assert hashlib.sha256(Path(base['source']).read_bytes()).hexdigest()==base['source_sha256'];a=next(x for x in base['frames'] if x['name']==name);b=next(x for x in candidate['frames'] if x['name']==name)
 for k in ['device','lighting_policy','lighting_overrides','denoising','renderer_sha256']:assert base[k]==candidate[k],k
